#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

ENDPOINT="https://www.mrsassessors.com/api/revalidate"
PROBE_BODY='{"sys":{"type":"Entry","contentType":{"sys":{"id":"wizardProbe"}}}}'

probe() {
  curl -s -o /dev/null -w '%{http_code}' --max-time 15 -X POST \
    -H 'content-type: application/json' "$@" -d "$PROBE_BODY" "$ENDPOINT" || printf '000'
}

probe_with() {
  probe -H @<(printf 'x-webhook-secret: %s\n' "$1")
}

to_clipboard() {
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}

hand_over_secret() {
  if to_clipboard "$WEBHOOK_SECRET"; then
    printf '  %s✓ copied%s the production secret to your clipboard\n' "$GREEN" "$RESET"
  else
    warn "no clipboard tool found, so the secret is printed below. Clear your scrollback afterwards."
    printf '\n    %s\n\n' "$WEBHOOK_SECRET"
  fi
}

run_wizard() {

TOTAL_STAGES=6

command -v curl >/dev/null 2>&1    || { warn "curl is required."; exit 1; }
command -v openssl >/dev/null 2>&1 || { warn "openssl is required."; exit 1; }

SPACE_ID=$(_existing CONTENTFUL_SPACE_ID || true)
DEV_SECRET=$(_existing CONTENTFUL_WEBHOOK_SECRET || true)
if [[ -n "$SPACE_ID" ]]; then
  CONTENTFUL_SPACE="https://app.contentful.com/spaces/$SPACE_ID"
else
  CONTENTFUL_SPACE="https://app.contentful.com"
fi

banner "Content webhook: CONTENTFUL_WEBHOOK_SECRET in production"
ROTATING=0

stage "Preflight: is the endpoint deployed?"
say "Probing $ENDPOINT with no secret."
while :; do
  code=$(probe)
  case "$code" in
    503) say "Got 503: the endpoint is live and the secret is not set yet. Good to go."; break ;;
    401) say "Got 401: a secret is already set in production, so this run rotates it."
         ROTATING=1; break ;;
    404) warn "Got 404: production is not running the code that has /api/revalidate."
         note "Deploy feat/refactor-site (the App Router site) to production first." ;;
    *)   warn "Got $code: expected 503 (unset) or 401 (already set)." ;;
  esac
  confirm "Probe again?" || { warn "Stopped before changing anything."; exit 1; }
done
pause "Press Enter to continue"

stage "Generate the production secret"
WEBHOOK_SECRET=""
if (( ROTATING )) && confirm "Resuming a run where you already put a new secret on the server?"; then
  ask_secret WEBHOOK_SECRET "Paste the secret you set on the server:"
else
  WEBHOOK_SECRET=$(openssl rand -hex 32)
  say "Generated a fresh 64-character secret with openssl rand -hex 32."
fi
if [[ -z "$WEBHOOK_SECRET" ]]; then warn "No secret, so nothing to configure."; exit 1; fi
if [[ -n "$DEV_SECRET" && "$WEBHOOK_SECRET" == "$DEV_SECRET" ]]; then
  warn "That is the development secret from $ENV_FILE. Production needs its own value."; exit 1
fi
note "It is held in memory only: not written to $ENV_FILE, not set as a GitHub secret."
note "It goes in exactly two places: the production environment and the Contentful header."
note "If you quit after the server step, re-run and choose to resume, pasting the same value."
pause "Press Enter to continue"

stage "Set it in the production environment"
hand_over_secret
step "SSH to the production host (Next.js behind nginx on Ubuntu)."
step "Find where CONTENTFUL_ACCESS_KEY is supplied: the app's .env, a pm2 ecosystem"
say  "  file, or a systemd unit's EnvironmentFile=. Put the new variable beside it."
step "Add (or replace) this line, pasting the secret from your clipboard:"
say  "  ${BOLD}CONTENTFUL_WEBHOOK_SECRET=<paste>${RESET}"
step "Restart the Next.js process (pm2 restart <app>, systemctl restart <unit>, ...)."
note "The process only sees a new environment after a restart."
pause "Press Enter once the process has restarted"
while :; do
  code=$(probe_with "$WEBHOOK_SECRET")
  case "$code" in
    200) say "Got 200 with the new secret: production has it."; break ;;
    503) warn "Got 503: the variable is not in the running process. Was it restarted?" ;;
    401) warn "Got 401: the running process has a different value. Check for a typo or an old line." ;;
    *)   warn "Got $code: expected 200." ;;
  esac
  confirm "Fix it and probe again?" || { warn "Stopped. Production is not confirmed."; exit 1; }
done
pause "Press Enter to continue"

stage "Create the webhook in Contentful"
hand_over_secret
open_url "$CONTENTFUL_SPACE/settings/webhooks"
if (( ROTATING )); then
  step "Open the existing ${BOLD}revalidate-production${RESET} webhook."
  step "Replace the value of the ${BOLD}X-Webhook-Secret${RESET} header with your clipboard. Save."
  note "Publishes in between log 401 and wait for the hourly regeneration. That is harmless."
else
  step "Click ${BOLD}Add webhook${RESET}."
  step "Name: ${BOLD}revalidate-production${RESET}"
  step "URL: ${BOLD}POST${RESET} ${BOLD}$ENDPOINT${RESET}"
  step "Triggers: choose specific events. Tick ${BOLD}Entry${RESET} and ${BOLD}Asset${RESET},"
  say  "  for ${BOLD}Publish${RESET} and ${BOLD}Unpublish${RESET} only. Leave create, save, archive, delete off."
  step "Headers: ${BOLD}Add secret header${RESET}, key ${BOLD}X-Webhook-Secret${RESET}, value from your clipboard."
  step "Payload: leave the default."
  step "Save."
fi
pause "Press Enter once the webhook is saved"

stage "Publish an Article and watch it land"
open_url "$CONTENTFUL_SPACE/entries"
step "Open any Article (content type mrsBlog), make a trivial edit, and ${BOLD}Publish${RESET}."
step "Back in Settings → Webhooks → revalidate-production → ${BOLD}Activity log${RESET}."
say  "  The newest call should be ${BOLD}200${RESET} with {\"revalidated\":[\"content:mrsBlog\"]}."
note "401 means the header and the server disagree. 503 means the restart was missed."
pause "Press Enter once the activity log shows 200"
open_url "https://www.mrsassessors.com/"
step "Open that Article on the site and confirm the edit is there already."
note "The first load after a revalidation may serve the old page once, then the new one."
confirm "Is the edit live?" || { warn "Not confirmed. Re-check the activity log before going on."; exit 1; }

stage "Confirm the endpoint is closed"
no_secret=$(probe)
wrong_secret=$(probe_with "wrong-$(openssl rand -hex 8)")
say "No secret:    $no_secret"
say "Wrong secret: $wrong_secret"
if [[ "$no_secret" == 401 && "$wrong_secret" == 401 ]]; then
  printf '  %s✓ both refused with 401%s\n' "$GREEN" "$RESET"
else
  warn "Both must be 401. Anything else means the secret is not being checked."
  SKIPPED+=("endpoint is not refusing unauthenticated calls (got $no_secret / $wrong_secret)")
fi
if to_clipboard ""; then note "Cleared the clipboard."; fi
pause "Press Enter to finish"

finish
say "CONTENTFUL_WEBHOOK_SECRET is set in production and the Contentful webhook carries it."
say "Nothing was written to $ENV_FILE or to GitHub."
}

run_wizard "$@"; exit
